import{_ as t,o as s,c as o,ag as i}from"./chunks/framework.ClKCtVAA.js";const g=JSON.parse('{"title":"Issue tracker: GitHub","description":"","frontmatter":{},"headers":[],"relativePath":"agents/issue-tracker.md","filePath":"agents/issue-tracker.md","lastUpdated":1785589784000}'),a={name:"agents/issue-tracker.md"};function n(r,e,l,d,c,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="issue-tracker-github" tabindex="-1">Issue tracker: GitHub <a class="header-anchor" href="#issue-tracker-github" aria-label="Permalink to &quot;Issue tracker: GitHub&quot;">​</a></h1><p>Issues and PRDs for this repo live as GitHub issues. Use the <code>gh</code> CLI for all operations.</p><h2 id="conventions" tabindex="-1">Conventions <a class="header-anchor" href="#conventions" aria-label="Permalink to &quot;Conventions&quot;">​</a></h2><ul><li><strong>Create an issue</strong>: <code>gh issue create --title &quot;...&quot; --body &quot;...&quot;</code>. Use a heredoc for multi-line bodies.</li><li><strong>Read an issue</strong>: <code>gh issue view &lt;number&gt; --comments</code>, filtering comments by <code>jq</code> and also fetching labels.</li><li><strong>List issues</strong>: <code>gh issue list --state open --json number,title,body,labels,comments --jq &#39;[.[] | {number, title, body, labels: [.labels[].name], comments: [.comments[].body]}]&#39;</code> with appropriate <code>--label</code> and <code>--state</code> filters.</li><li><strong>Comment on an issue</strong>: <code>gh issue comment &lt;number&gt; --body &quot;...&quot;</code></li><li><strong>Apply / remove labels</strong>: <code>gh issue edit &lt;number&gt; --add-label &quot;...&quot;</code> / <code>--remove-label &quot;...&quot;</code></li><li><strong>Close</strong>: <code>gh issue close &lt;number&gt; --comment &quot;...&quot;</code></li></ul><p>Infer the repo from <code>git remote -v</code> — <code>gh</code> does this automatically when run inside a clone.</p><h2 id="pull-requests-as-a-triage-surface" tabindex="-1">Pull requests as a triage surface <a class="header-anchor" href="#pull-requests-as-a-triage-surface" aria-label="Permalink to &quot;Pull requests as a triage surface&quot;">​</a></h2><p><strong>PRs as a request surface: no.</strong></p><h2 id="when-a-skill-says-publish-to-the-issue-tracker" tabindex="-1">When a skill says &quot;publish to the issue tracker&quot; <a class="header-anchor" href="#when-a-skill-says-publish-to-the-issue-tracker" aria-label="Permalink to &quot;When a skill says &quot;publish to the issue tracker&quot;&quot;">​</a></h2><p>Create a GitHub issue.</p><h2 id="when-a-skill-says-fetch-the-relevant-ticket" tabindex="-1">When a skill says &quot;fetch the relevant ticket&quot; <a class="header-anchor" href="#when-a-skill-says-fetch-the-relevant-ticket" aria-label="Permalink to &quot;When a skill says &quot;fetch the relevant ticket&quot;&quot;">​</a></h2><p>Run <code>gh issue view &lt;number&gt; --comments</code>.</p><h2 id="wayfinding-operations" tabindex="-1">Wayfinding operations <a class="header-anchor" href="#wayfinding-operations" aria-label="Permalink to &quot;Wayfinding operations&quot;">​</a></h2><p>Used by <code>/wayfinder</code>. The <strong>map</strong> is a single issue with <strong>child</strong> issues as tickets.</p><ul><li><strong>Map</strong>: a single issue labelled <code>wayfinder:map</code>, holding the Notes / Decisions-so-far / Fog body. <code>gh issue create --label wayfinder:map</code>.</li><li><strong>Child ticket</strong>: an issue linked to the map as a GitHub sub-issue (<code>gh api</code> on the sub-issues endpoint). Where sub-issues aren&#39;t enabled, add the child to a task list in the map body and put <code>Part of #&lt;map&gt;</code> at the top of the child body. Labels: <code>wayfinder:&lt;type&gt;</code> (<code>research</code>/<code>prototype</code>/<code>grilling</code>/<code>task</code>). Once claimed, the ticket is assigned to the driving dev.</li><li><strong>Blocking</strong>: GitHub&#39;s <strong>native issue dependencies</strong> — the canonical, UI-visible representation. Add an edge with <code>gh api --method POST repos/&lt;owner&gt;/&lt;repo&gt;/issues/&lt;child&gt;/dependencies/blocked_by -F issue_id=&lt;blocker-db-id&gt;</code>, where <code>&lt;blocker-db-id&gt;</code> is the blocker&#39;s numeric database id (<code>gh api repos/&lt;owner&gt;/&lt;repo&gt;/issues/&lt;n&gt; --jq .id</code>, not the <code>#number</code> or <code>node_id</code>). GitHub reports <code>issue_dependencies_summary.blocked_by</code> (open blockers only — the live gate). Where dependencies aren&#39;t available, fall back to a <code>Blocked by: #&lt;n&gt;, #&lt;n&gt;</code> line at the top of the child body. A ticket is unblocked when every blocker is closed.</li><li><strong>Frontier query</strong>: list the map&#39;s open children (<code>gh issue list --state open</code>, scoped to the map&#39;s sub-issues / task list), drop any with an open blocker (<code>issue_dependencies_summary.blocked_by &gt; 0</code>, or an open issue in the <code>Blocked by</code> line) or an assignee; first in map order wins.</li><li><strong>Claim</strong>: <code>gh issue edit &lt;n&gt; --add-assignee @me</code> — the session&#39;s first write.</li><li><strong>Resolve</strong>: <code>gh issue comment &lt;n&gt; --body &quot;&lt;answer&gt;&quot;</code>, then <code>gh issue close &lt;n&gt;</code>, then append a context pointer (gist + link) to the map&#39;s Decisions-so-far.</li></ul>',14)])])}const p=t(a,[["render",n]]);export{g as __pageData,p as default};
